// Functional tests of making Cards (#15, PRD 4.5.2, F12, F16) through the HTTP API, with Books generated by playing
// the worker over /internal with segments of fake AAC frames (ts-fixture.ts), so the API really cuts their audio.
import { eq } from "drizzle-orm";
import { describe, expect, it } from "vitest";
import { fakeAiProvider } from "../src/ai/fake.js";
import type { AiProvider, AiRequest } from "../src/ai/provider.js";
import { splitAdts } from "../src/cards/audio-clip.js";
import {
  CARD_BACK_FAILED_MESSAGE,
  DAILY_AI_CALLS,
  type ApiError,
  type BookDetail,
  type Card,
  type ClaimedRenderJob,
  type CreateCard,
  type ParseResult,
} from "../src/contract.js";
import { allowlist, cards, marks } from "../src/db/schema.js";
import {
  claimJob,
  generatedBook,
  logIn,
  renderAll,
  reportRenderResult,
  testApp,
  withCookie,
  type SegmentBytes,
  type TestApp,
} from "./helpers.js";
import { fakeTsSegment } from "./ts-fixture.js";

type T = Awaited<ReturnType<typeof testApp>>;
const s = (text: string) => ({ paragraphIndex: 0, text, spokenText: text });

/** Each Sentence lasts 4 s, one segment each: Sentence i plays from i × 4 s to 300 ms before the next. */
const CHAPTERS: ParseResult["chapters"] = [
  { title: "Imprint", skipped: true, sentences: [s("This ebook is in the public domain.")] },
  {
    title: "I",
    sentences: [
      s("She took it for granted that he would come."),
      s("She runs a bakery in the village."),
      s("It was granted at last."),
    ],
  },
];

/** Segments of fake AAC frames, each frame tagged with its Sentence's index plus `voiceTag`. */
const tsSegments =
  (voiceTag = 0): SegmentBytes =>
  (sentence, durationMs) =>
    fakeTsSegment(durationMs, sentence.index + voiceTag);

interface Setup extends T {
  book: BookDetail;
  /** The narrated Chapter's Sentences, by index. */
  ids: string[];
  texts: string[];
  imprintId: string;
}

async function setUp(options: { ai?: AiProvider } = {}): Promise<Setup> {
  const t = await testApp(options);
  const book = await generatedBook(t, "Pride and Prejudice", CHAPTERS, tsSegments());
  const sentencesOf = async (chapterId: string) =>
    (await (await t.app.request(`/api/chapters/${chapterId}/sentences`)).json()) as { id: string; text: string }[];
  const narrated = await sentencesOf(book.chapters[1]!.id);
  const [imprint] = await sentencesOf(book.chapters[0]!.id);
  return { ...t, book, ids: narrated.map((x) => x.id), texts: narrated.map((x) => x.text), imprintId: imprint!.id };
}

function postCard(app: TestApp, body: CreateCard) {
  return app.request("/api/cards", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
}

/** Makes a Card of the first occurrence of `selected` in the Sentence. */
async function makeCard(t: Setup, index: number, selected: string, extra: Partial<CreateCard> = {}) {
  const start = t.texts[index]!.indexOf(selected);
  if (start < 0) throw new Error(`${selected} is not in Sentence ${index}`);
  const res = await postCard(t.app, { sentenceId: t.ids[index]!, start, end: start + selected.length, ...extra });
  return { status: res.status, body: (await res.json()) as Card & ApiError };
}

async function bookCards(app: TestApp, bookId: string): Promise<Card[]> {
  const res = await app.request(`/api/books/${bookId}/cards`);
  expect(res.status).toBe(200);
  return (await res.json()) as Card[];
}

/** The frames of a Card's audio, by the tag each carries. */
async function audioTags(app: TestApp, cardId: string): Promise<number[]> {
  const res = await app.request(`/api/cards/${cardId}/audio`);
  expect(res.status).toBe(200);
  expect(res.headers.get("Content-Type")).toBe("audio/aac");
  return splitAdts(new Uint8Array(await res.arrayBuffer())).map((f) => f[7]!);
}

/** Answers like the fake until `failing` is set, recording every request. */
function switchableAi(): AiProvider & { failing: boolean; requests: AiRequest[] } {
  const fake = fakeAiProvider();
  const ai = {
    model: "switchable",
    failing: false,
    requests: [] as AiRequest[],
    async *stream(request: AiRequest, signal: AbortSignal) {
      ai.requests.push(request);
      if (ai.failing) throw new Error("provider down");
      yield* fake.stream(request, signal);
    },
  };
  return ai;
}

describe("POST /api/cards (制作卡片, PRD 4.5.2)", () => {
  it("makes a word Card widened to the whole word, with its snapshot, back and due now (AC-CARD-01)", async () => {
    const t = await setUp();

    const { status, body } = await makeCard(t, 0, "grant");

    expect(status).toBe(201);
    expect(body).toEqual({
      id: expect.any(String),
      sentenceId: t.ids[0],
      targetText: "granted",
      targetKind: "word",
      targetStart: 16,
      targetEnd: 23,
      sentenceText: "She took it for granted that he would come.",
      contextBefore: null,
      contextAfter: "She runs a bakery in the village.",
      bookTitle: "Pride and Prejudice",
      back: {
        kind: "word",
        meaning: "（示例释义）granted",
        phonetic: "/ˈsæmpəl/",
        partOfSpeech: "v.",
        collocations: ["granted sth：示例搭配"],
      },
      hasAudio: true,
      due: "2026-11-18T00:00:00.000Z",
      createdAt: "2026-11-18T00:00:00.000Z",
    });
    expect(await bookCards(t.app, t.book.id)).toEqual([body]);
  });

  it("makes phrase and whole-Sentence Cards by how many words are selected (AC-CARD-02, AC-CARD-03)", async () => {
    const t = await setUp();

    const phrase = await makeCard(t, 0, "took it for gran");
    const whole = await makeCard(t, 1, "She runs a bakery in the village");

    expect(phrase.body).toMatchObject({ targetText: "took it for granted", targetKind: "phrase" });
    expect(phrase.body.back).toMatchObject({ kind: "phrase", example: "An example with took it for granted." });
    expect(whole.body).toMatchObject({ targetKind: "sentence", targetStart: 0, targetEnd: t.texts[1]!.length });
    expect(whole.body.back).toMatchObject({ kind: "sentence", translation: `（示例意译）${t.texts[1]}` });
    expect(whole.body).toMatchObject({ contextBefore: t.texts[0], contextAfter: t.texts[2] });
  });

  it("explains the Target in its Sentence's context, the Book's text as data (AC-CARD-04)", async () => {
    const ai = switchableAi();
    const t = await setUp({ ai });

    await makeCard(t, 1, "runs");

    const [request] = ai.requests;
    expect(request!.hint).toEqual({ kind: "card", sentence: t.texts[1], target: "runs", targetKind: "word" });
    const prompt = request!.messages[0]!.content;
    expect(prompt).toContain("<target_sentence>She runs a bakery in the village.</target_sentence>");
    expect(prompt).toContain("<target>runs</target>");
    expect(prompt).toContain(`<before>${t.texts[0]}</before>`);
    expect(request!.system).toContain("在这句话里的意思");
  });

  it("opens the Card of the same Target of the Sentence instead of making another (AC-CARD-09)", async () => {
    const t = await setUp();
    const first = await makeCard(t, 0, "for granted");

    const again = await makeCard(t, 0, "or grant");

    expect(again).toEqual({ status: 200, body: first.body });
    expect(await bookCards(t.app, t.book.id)).toHaveLength(1);
  });

  it("asks before making a second Card of a Target text from another Sentence, then keeps both (AC-CARD-05)", async () => {
    const t = await setUp();
    const first = await makeCard(t, 0, "granted");

    const asked = await makeCard(t, 2, "Granted".toLowerCase());
    expect(asked.status).toBe(409);
    expect(asked.body.error).toEqual({ code: "duplicate_target", message: '你已有 "granted" 的卡片，仍要创建吗？' });
    expect(await bookCards(t.app, t.book.id)).toHaveLength(1);

    const made = await makeCard(t, 2, "granted", { allowDuplicate: true });
    expect(made.status).toBe(201);
    expect((await bookCards(t.app, t.book.id)).map((c) => c.id)).toEqual([first.body.id, made.body.id]);
  });

  it("lets one Sentence have several Cards, overlapping too, in reading order", async () => {
    const t = await setUp();
    const late = await makeCard(t, 0, "come");
    const early = await makeCard(t, 0, "took");
    const whole = await makeCard(t, 0, t.texts[0]!);

    expect((await bookCards(t.app, t.book.id)).map((c) => c.id)).toEqual([whole.body.id, early.body.id, late.body.id]);
  });

  it("makes one Card when the same Target is asked for twice at once (a double click)", async () => {
    const t = await setUp();
    const body = { sentenceId: t.ids[0]!, start: 16, end: 23 };

    const [a, b] = await Promise.all([postCard(t.app, body), postCard(t.app, body)]);

    expect([a.status, b.status].sort()).toEqual([200, 201]);
    expect(((await a.json()) as Card).id).toBe(((await b.json()) as Card).id);
    expect(await t.db.select().from(cards)).toHaveLength(1);
    // The loser's audio copy is not left behind.
    expect([...t.storage.objects.keys()].filter((k) => k.startsWith("cards/"))).toHaveLength(1);
  });

  it("refuses a selection without a word, and Sentences not on the user's Shelf", async () => {
    const t = await setUp();
    expect((await postCard(t.app, { sentenceId: t.ids[0]!, start: 3, end: 4 })).status).toBe(400);
    expect((await postCard(t.app, { sentenceId: crypto.randomUUID(), start: 0, end: 3 })).status).toBe(404);

    await t.db.insert(allowlist).values({ email: "other@example.com" });
    const other = withCookie(t.anon, await logIn(t, "other@example.com"));
    expect((await postCard(other, { sentenceId: t.ids[0]!, start: 0, end: 3 })).status).toBe(404);
    expect((await other.request(`/api/books/${t.book.id}/cards`)).status).toBe(404);
  });
});

describe("a Card's audio (AC-CARD-07)", () => {
  it("is the Sentence's own part of the audio, cut by its timeline", async () => {
    const t = await setUp();
    const { body } = await makeCard(t, 1, "bakery");

    const tags = await audioTags(t.app, body.id);

    // Sentence 1 plays from 4 s to 7.7 s: 87 frames of 1024 samples at 24 kHz, all from its own segment.
    expect(tags).toHaveLength(87);
    expect(new Set(tags)).toEqual(new Set([1]));
  });

  it("stays the same after the Book's Voice changes, even once the old Voice's audio is deleted", async () => {
    const t = await setUp();
    const { body } = await makeCard(t, 1, "bakery");
    const before = await audioTags(t.app, body.id);

    // Two changes: the second deletes the first Voice's segments (jobs/voice-change.ts).
    for (const [voice, tag] of [["uk_male", 10], ["us_male", 20]] as const) {
      const res = await t.app.request(`/api/books/${t.book.id}/voice`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ voice }),
      });
      expect(res.status).toBe(202);
      for (let job = await claimJob(t.app); job; job = await claimJob(t.app)) {
        const report = await renderAll(t.storage, job as ClaimedRenderJob, 4000, tsSegments(tag));
        expect((await reportRenderResult(t.app, job, report)).status).toBe(204);
      }
    }

    expect(await audioTags(t.app, body.id)).toEqual(before);
    // A Card made now copies the new Voice.
    const fresh = await makeCard(t, 1, "village");
    expect(new Set(await audioTags(t.app, fresh.body.id))).toEqual(new Set([21]));
  });

  it("is missing for a Sentence without audio (a Skipped Chapter), and only its owner gets it", async () => {
    const t = await setUp();
    const skipped = await postCard(t.app, { sentenceId: t.imprintId, start: 0, end: 4 });
    const card = (await skipped.json()) as Card;
    expect(card.hasAudio).toBe(false);
    expect((await t.app.request(`/api/cards/${card.id}/audio`)).status).toBe(404);

    const { body } = await makeCard(t, 0, "come");
    await t.db.insert(allowlist).values({ email: "other@example.com" });
    const other = withCookie(t.anon, await logIn(t, "other@example.com"));
    expect((await other.request(`/api/cards/${body.id}/audio`)).status).toBe(404);
  });

  it("outlives its Book: the Card loses its Sentence but keeps its text and audio", async () => {
    const t = await setUp();
    const { body } = await makeCard(t, 1, "bakery");
    const tags = await audioTags(t.app, body.id);

    expect((await t.app.request(`/api/books/${t.book.id}`, { method: "DELETE" })).status).toBe(204);

    const [row] = await t.db.select().from(cards).where(eq(cards.id, body.id));
    expect(row).toMatchObject({ sentenceId: null, sentenceText: t.texts[1], targetText: "bakery" });
    expect(await audioTags(t.app, body.id)).toEqual(tags);
  });
});

describe("a Card's back (AC-CARD-04, PRD 4.5.2 规则 5, 6)", () => {
  it("is null when the AI fails, the Card made anyway; retrying generates it, never counting AI calls", async () => {
    const ai = switchableAi();
    const t = await setUp({ ai });
    ai.failing = true;

    const { status, body } = await makeCard(t, 1, "runs");
    expect(status).toBe(201);
    expect(body.back).toBeNull();

    const failedAgain = await t.app.request(`/api/cards/${body.id}/back`, { method: "POST" });
    expect(failedAgain.status).toBe(502);
    expect(((await failedAgain.json()) as ApiError).error.message).toBe(CARD_BACK_FAILED_MESSAGE);

    ai.failing = false;
    const retried = await t.app.request(`/api/cards/${body.id}/back`, { method: "POST" });
    expect(retried.status).toBe(200);
    const card = (await retried.json()) as Card;
    expect(card.back).toMatchObject({ kind: "word", meaning: "（示例释义）runs" });
    expect((await bookCards(t.app, t.book.id))[0]!.back).toEqual(card.back);

    const explanation = (await (await t.app.request(`/api/sentences/${t.ids[1]}/explanation`)).json()) as { aiRemaining: number };
    expect(explanation.aiRemaining).toBe(DAILY_AI_CALLS);
  });

  it("is null when the AI answers something that is not a back", async () => {
    const t = await setUp({
      ai: {
        model: "chatty",
        async *stream() {
          yield "当然！这个词的意思是经营。";
        },
      },
    });
    expect((await makeCard(t, 1, "runs")).body.back).toBeNull();
  });

  it("is 404 to retry for another user's Card", async () => {
    const t = await setUp();
    const { body } = await makeCard(t, 1, "runs");
    await t.db.insert(allowlist).values({ email: "other@example.com" });
    const other = withCookie(t.anon, await logIn(t, "other@example.com"));
    expect((await other.request(`/api/cards/${body.id}/back`, { method: "POST" })).status).toBe(404);
  });
});

describe("making a Card processes the Sentence's Mark (PRD 4.4.4, AC-CARD-06, AC-CARD-10)", () => {
  async function gleaningCount(app: TestApp) {
    return ((await (await app.request("/api/gleanings/count")).json()) as { count: number }).count;
  }

  it("takes a marked Sentence out of Gleanings and the Book's pending Marks", async () => {
    const t = await setUp();
    await t.app.request(`/api/sentences/${t.ids[1]}/mark`, { method: "PUT" });
    expect(await gleaningCount(t.app)).toBe(1);

    await makeCard(t, 1, "a bakery");

    expect(await gleaningCount(t.app)).toBe(0);
    expect(await (await t.app.request(`/api/books/${t.book.id}/marks`)).json()).toEqual({ pending: [] });
    const [mark] = await t.db.select().from(marks);
    expect(mark!.status).toBe("processed");
  });

  it("marks nothing when the Sentence was not marked (制卡 straight from the reading view, PRD 4.5.2 规则 8)", async () => {
    const t = await setUp();
    await makeCard(t, 1, "bakery");
    expect(await t.db.select().from(marks)).toEqual([]);
  });
});
